// src/progress.ts
class ProgressTracker {
  steps = new Map;
  lastMessageAt = new Map;
  lastTaskAt = new Map;
  busySince = new Map;
  peerMessages = new Map;
  reported = new Set;
  chattyReported = new Set;
  maxSteps;
  constructor(maxSteps = 10) {
    this.maxSteps = maxSteps;
  }
  recordStep(sessionId, outputTokens) {
    const records = this.steps.get(sessionId) ?? [];
    records.push({ outputTokens, timestamp: Date.now() });
    if (records.length > this.maxSteps)
      records.shift();
    this.steps.set(sessionId, records);
  }
  recordPeerMessage(sessionId) {
    const timestamps = this.peerMessages.get(sessionId) ?? [];
    timestamps.push(Date.now());
    this.peerMessages.set(sessionId, timestamps);
  }
  isChatty(sessionId, limit, windowMs) {
    if (limit === 0)
      return false;
    const timestamps = this.peerMessages.get(sessionId);
    if (!timestamps)
      return false;
    const cutoff = Date.now() - windowMs;
    const recent = timestamps.filter((t) => t >= cutoff);
    this.peerMessages.set(sessionId, recent);
    return recent.length >= limit;
  }
  markChattyReported(sessionId) {
    this.chattyReported.add(sessionId);
  }
  isChattyReported(sessionId) {
    return this.chattyReported.has(sessionId);
  }
  clearChattyReport(sessionId) {
    this.chattyReported.delete(sessionId);
  }
  recordMessage(sessionId) {
    this.lastMessageAt.set(sessionId, Date.now());
    this.clearReport(sessionId);
  }
  recordTaskComplete(sessionId) {
    this.lastTaskAt.set(sessionId, Date.now());
    this.clearReport(sessionId);
  }
  isTokenStalled(sessionId, minSteps, threshold) {
    const records = this.steps.get(sessionId);
    if (!records || records.length < minSteps)
      return false;
    const recent = records.slice(-minSteps);
    return recent.every((r) => r.outputTokens < threshold);
  }
  recordBusyStart(sessionId) {
    this.busySince.set(sessionId, Date.now());
  }
  lastActivityAt(sessionId) {
    const records = this.steps.get(sessionId);
    const lastStepAt = records && records.length > 0 ? records[records.length - 1].timestamp : 0;
    return Math.max(this.lastMessageAt.get(sessionId) ?? 0, this.lastTaskAt.get(sessionId) ?? 0, lastStepAt, this.busySince.get(sessionId) ?? 0);
  }
  isTimeStalled(sessionId, thresholdMs) {
    const baseline = this.lastActivityAt(sessionId);
    if (baseline === 0)
      return false;
    return Date.now() - baseline >= thresholdMs;
  }
  markReported(sessionId) {
    this.reported.add(sessionId);
  }
  isReported(sessionId) {
    return this.reported.has(sessionId);
  }
  clearReport(sessionId) {
    this.reported.delete(sessionId);
  }
  remove(sessionId) {
    this.steps.delete(sessionId);
    this.lastMessageAt.delete(sessionId);
    this.lastTaskAt.delete(sessionId);
    this.busySince.delete(sessionId);
    this.peerMessages.delete(sessionId);
    this.reported.delete(sessionId);
    this.chattyReported.delete(sessionId);
  }
}

// src/config.ts
import { readFileSync } from "node:fs";
import path2 from "node:path";
var DEFAULT_CONFIG = {
  mergeOnCleanup: true,
  stallThresholdMs: 300000,
  stallMinSteps: 5,
  stallTokenThreshold: 200,
  timeoutMs: 30 * 60 * 1000,
  rateLimitCapacity: 10,
  dashboardPort: 4747,
  peerMessageLimit: 5,
  peerMessageWindowMs: 300000,
  defaultModel: "",
  modelPool: [],
  modelsByAgent: {},
  modelAssignment: "default",
  promptForModels: false,
  silentLead: true
};
function readConfigFile(filePath) {
  try {
    const text = readFileSync(filePath, "utf-8");
    const raw = JSON.parse(text);
    const result3 = {};
    if (typeof raw.mergeOnCleanup === "boolean")
      result3.mergeOnCleanup = raw.mergeOnCleanup;
    if (typeof raw.stallThresholdMs === "number")
      result3.stallThresholdMs = raw.stallThresholdMs;
    if (typeof raw.stallMinSteps === "number")
      result3.stallMinSteps = raw.stallMinSteps;
    if (typeof raw.stallTokenThreshold === "number")
      result3.stallTokenThreshold = raw.stallTokenThreshold;
    if (typeof raw.timeoutMs === "number")
      result3.timeoutMs = raw.timeoutMs;
    if (typeof raw.rateLimitCapacity === "number")
      result3.rateLimitCapacity = raw.rateLimitCapacity;
    if (typeof raw.dashboardPort === "number")
      result3.dashboardPort = raw.dashboardPort;
    if (typeof raw.peerMessageLimit === "number")
      result3.peerMessageLimit = raw.peerMessageLimit;
    if (typeof raw.peerMessageWindowMs === "number")
      result3.peerMessageWindowMs = raw.peerMessageWindowMs;
    if (typeof raw.defaultModel === "string")
      result3.defaultModel = raw.defaultModel;
    if (Array.isArray(raw.modelPool) && raw.modelPool.every((m) => typeof m === "string"))
      result3.modelPool = raw.modelPool;
    if (typeof raw.modelsByAgent === "object" && raw.modelsByAgent !== null && !Array.isArray(raw.modelsByAgent)) {
      const valid = Object.entries(raw.modelsByAgent).every(([, v]) => typeof v === "string");
      if (valid)
        result3.modelsByAgent = raw.modelsByAgent;
    }
    if (typeof raw.modelAssignment === "string" && ["default", "rotate", "random"].includes(raw.modelAssignment))
      result3.modelAssignment = raw.modelAssignment;
    if (typeof raw.promptForModels === "boolean")
      result3.promptForModels = raw.promptForModels;
    if (typeof raw.silentLead === "boolean")
      result3.silentLead = raw.silentLead;
    return result3;
  } catch (err) {
    if (err && typeof err === "object" && "code" in err && err.code === "ENOENT")
      return {};
    console.warn(`[ensemble] Invalid config at ${filePath}, using defaults`);
    return {};
  }
}
function loadConfig(projectDir) {
  const homeDir = process.env.HOME ?? process.env.USERPROFILE ?? "";
  const globalPath = path2.join(homeDir, ".config", "opencode", "ensemble.json");
  const projectPath = path2.join(projectDir, ".opencode", "ensemble.json");
  const global2 = readConfigFile(globalPath);
  const project = readConfigFile(projectPath);
  const merged = { ...DEFAULT_CONFIG, ...global2, ...project };
  const timeout3 = process.env.OPENCODE_ENSEMBLE_TIMEOUT;
  if (timeout3 !== undefined)
    merged.timeoutMs = timeout3 === "0" ? 0 : parseInt(timeout3, 10) || merged.timeoutMs;
  const rateLimit = process.env.OPENCODE_ENSEMBLE_RATE_LIMIT;
  if (rateLimit !== undefined)
    merged.rateLimitCapacity = rateLimit === "0" ? 0 : parseInt(rateLimit, 10) || merged.rateLimitCapacity;
  const stall = process.env.STALL_THRESHOLD_MS;
  if (stall !== undefined)
    merged.stallThresholdMs = stall === "0" ? 0 : parseInt(stall, 10) || merged.stallThresholdMs;
  return merged;
}

// src/rate-limit.ts
class TokenBucket {
  tokens;
  capacity;
  refillRate;
  refillIntervalMs;
  lastRefill;
  disabled;
  constructor(opts) {
    this.disabled = opts.capacity === 0;
    this.capacity = opts.capacity;
    this.tokens = opts.capacity;
    this.refillRate = opts.refillRate;
    this.refillIntervalMs = opts.refillIntervalMs;
    this.lastRefill = Date.now();
  }
  refill() {
    if (this.disabled)
      return;
    const now3 = Date.now();
    const elapsed = now3 - this.lastRefill;
    if (elapsed < this.refillIntervalMs)
      return;
    const intervals = Math.floor(elapsed / this.refillIntervalMs);
    this.tokens = Math.min(this.capacity, this.tokens + intervals * this.refillRate);
    this.lastRefill += intervals * this.refillIntervalMs;
  }
  tryConsume() {
    if (this.disabled)
      return true;
    this.refill();
    if (this.tokens > 0) {
      this.tokens--;
      return true;
    }
    return false;
  }
  async waitForToken(signal) {
    if (this.disabled)
      return;
    if (this.tryConsume())
      return;
    return new Promise((resolve2, reject) => {
      const checkInterval = Math.max(10, Math.floor(this.refillIntervalMs / 2));
      const timer = setInterval(() => {
        if (signal?.aborted) {
          clearInterval(timer);
          reject(new Error("Rate limit wait aborted"));
          return;
        }
        if (this.tryConsume()) {
          clearInterval(timer);
          resolve2();
        }
      }, checkInterval);
      signal?.addEventListener("abort", () => {
        clearInterval(timer);
        reject(new Error("Rate limit wait aborted"));
      }, { once: true });
    });
  }
}

// src/activity.ts
class ActivityBuffer {
  buffers = new Map;
  maxPerSession;
  constructor(options2) {
    this.maxPerSession = options2?.maxPerSession ?? 100;
  }
  record(sessionID, entry) {
    const entries3 = this.buffers.get(sessionID) ?? [];
    entries3.push(entry);
    if (entries3.length > this.maxPerSession) {
      entries3.splice(0, entries3.length - this.maxPerSession);
    }
    this.buffers.set(sessionID, entries3);
  }
  getActivity(sessionID, limit) {
    const entries3 = this.buffers.get(sessionID);
    if (!entries3)
      return [];
    if (limit !== undefined)
      return entries3.slice(-limit);
    return [...entries3];
  }
  remove(sessionID) {
    this.buffers.delete(sessionID);
  }
  has(sessionID) {
    const entries3 = this.buffers.get(sessionID);
    return entries3 !== undefined && entries3.length > 0;
  }
}
function recordFromV2Event(event, registry, buffer) {
  const props = event.properties;
  if (!props?.sessionID || !registry.getBySession(props.sessionID))
    return;
  if (event.type === "session.next.shell.started") {
    buffer.record(props.sessionID, { type: "shell_command", command: props.command, timestamp: Date.now() });
  } else if (event.type === "session.next.shell.ended") {
    buffer.record(props.sessionID, { type: "shell_command", exitCode: props.exitCode, timestamp: Date.now() });
  } else if (event.type === "session.next.step.ended") {
    buffer.record(props.sessionID, {
      type: "step",
      cost: props.cost,
      tokensIn: props.tokens?.input,
      tokensOut: props.tokens?.output,
      timestamp: Date.now()
    });
  }
}
function recordFromToolBefore(input, registry, buffer) {
  if (!registry.getBySession(input.sessionID))
    return;
  buffer.record(input.sessionID, { type: "tool_call", tool: input.tool, timestamp: Date.now() });
}
function recordFromToolAfter(input, output, registry, buffer) {
  if (!registry.getBySession(input.sessionID))
    return;
  buffer.record(input.sessionID, {
    type: "tool_result",
    tool: input.tool,
    title: output.title,
    output: output.output,
    timestamp: Date.now()
  });
}

// src/system-prompt.ts
function truncate2(s, maxLen) {
  return s.length > maxLen ? `${s.slice(0, maxLen)}...` : s;
}
var STATUS_DISPLAY = {
  busy: "working",
  ready: "idle",
  shutdown_requested: "shutting down",
  shutdown: "shut down",
  error: "error"
};
function leadReportDirective(config) {
  return config?.silentLead === false ? "You MUST send your results to the lead via team_message before stopping." : "Collaborate with teammates using team_message and complete assigned tasks on the board.";
}
function buildLeadSystemPrompt(db, teamId, config) {
  const team = db.query("SELECT name FROM team WHERE id = ?").get(teamId);
  if (!team)
    return "";
  const members = db.query("SELECT name, status FROM team_member WHERE team_id = ?").all(teamId);
  const taskCounts = db.query("SELECT status, COUNT(*) as count FROM team_task WHERE team_id = ? GROUP BY status").all(teamId);
  const countMap = {};
  for (const row of taskCounts) {
    countMap[row.status] = row.count;
  }
  const completed = countMap.completed ?? 0;
  const inProgress = countMap.in_progress ?? 0;
  const pending = countMap.pending ?? 0;
  const memberList = members.map((m) => `${m.name} [${STATUS_DISPLAY[m.status] ?? m.status}]`).join(", ");
  const teammateLine = members.length > 0 ? `Teammates: ${memberList}` : "Teammates: none";
  const pendingMessages = db.query("SELECT id, from_name, content FROM team_message WHERE team_id = ? AND to_name = 'lead' AND delivered = 0 ORDER BY time_created ASC").all(teamId);
  const lines = [
    `You are leading team "${team.name}" with ${members.length} active teammates.`,
    teammateLine,
    `Tasks: ${completed} completed, ${inProgress} in progress, ${pending} pending`
  ];
  const activeTasks = db.query("SELECT content, assignee FROM team_task WHERE team_id = ? AND status = 'in_progress' ORDER BY time_updated DESC LIMIT 5").all(teamId);
  const recentCompleted = db.query("SELECT content, assignee FROM team_task WHERE team_id = ? AND status = 'completed' ORDER BY time_updated DESC LIMIT 3").all(teamId);
  if (activeTasks.length > 0) {
    lines.push("Active tasks:");
    for (const t of activeTasks) {
      lines.push(`  [in_progress] ${truncate2(t.content, 120)}${t.assignee ? ` → ${t.assignee}` : ""}`);
    }
  }
  if (recentCompleted.length > 0) {
    lines.push("Recently completed:");
    for (const t of recentCompleted) {
      lines.push(`  [completed] ${truncate2(t.content, 120)}${t.assignee ? ` → ${t.assignee}` : ""}`);
    }
  }
  if (pendingMessages.length > 0) {
    lines.push("", "--- Team Messages ---");
    const MAX_MSG = 500;
    for (const msg of pendingMessages) {
      const parsed = parseTaskResult(msg.content);
      if (parsed) {
        const truncatedResult = { ...parsed, details: truncate2(parsed.details, 500) };
        lines.push(formatTaskResult(msg.from_name, truncatedResult));
      } else if (msg.content.length > MAX_MSG) {
        lines.push(`[From ${msg.from_name}]: ${msg.content.slice(0, MAX_MSG)}... (use team_results to read full message)`);
      } else {
        lines.push(`[From ${msg.from_name}]: ${msg.content}`);
      }
      markDelivered(db, msg.id);
    }
    lines.push("--- End Messages ---");
  }
  if (config?.promptForModels) {
    const poolOptions = config.modelPool && config.modelPool.length > 0 ? config.modelPool.map((m) => `      { label: "${m}", description: "" }`).join(`,
`) : "";
    lines.push("", "MODEL SELECTION:", "Before spawning teammates, use the question tool to ask the user about model preferences.", "Do NOT spawn any agents until the user confirms their model preference.", "Keep descriptions simple and clear — explain what each option means in plain language.", "Example question tool call:", '  question({ questions: [{ question: "Which AI models should your team agents use?", header: "Agent models", options: [', `    { label: "Same as me (Recommended)", description: "Every agent uses the same model I'm running on. Simplest option — no extra setup needed." },`, '    { label: "Mix of models", description: "Each agent gets a different model from your configured pool. Useful for getting diverse perspectives on the same problem." },', `    { label: "I'll choose per agent", description: "You pick the exact model for each agent as I spawn them. Most control, but requires a choice per agent." }`, "  ]}]})");
    if (poolOptions) {
      lines.push('If user picks "Mix of models", ask which models with multiple: true:', '  question({ questions: [{ question: "Which models should agents rotate through? Pick all that apply.", header: "Model pool", multiple: true, options: [', poolOptions, "  ]}]})");
    }
    lines.push(`If user picks "I'll choose per agent", ask for each agent's model individually before each team_spawn call.`, "Pass the chosen model via the model parameter on each team_spawn call.");
  }
  lines.push("", "Spawn teammates ONE AT A TIME. Wait for each tool result before spawning the next.", "This avoids git worktree contention. Once all are spawned, wait for their messages.", "Read-only agents (explore, plan) automatically skip worktree creation.", "For other agents that only need to read, pass worktree: false to avoid unnecessary isolation.", "", "Teammates work asynchronously and message you when done.", "Do NOT poll team_status or team_tasks_list repeatedly — wait for messages.", "After spawning all teammates, tell the user what you've set up and wait.", "When all teammates finish, summarize results and suggest next steps.", "", "MERGE WORKFLOW:", "After a teammate finishes and you shut them down, use team_merge to merge their branch.", "Do NOT tell teammates to commit — they handle that themselves.", "Do NOT run git merge manually — use team_merge which squash-merges and unstages for you.", "team_cleanup will safety-net merge any branches you forgot, but prefer explicit team_merge.", "", "Before calling team_cleanup, verify teammates have committed their work.", "team_shutdown will warn you if a teammate has uncommitted changes.", "team_cleanup will block if any worktree has uncommitted changes — merge or commit first.", 'To permanently delete archived teams, call team_cleanup with purge: ["team-name"] or purge: ["*"] for all archived teams.', "The first purge call is preview-only and deletes nothing.", "Use the question tool to ask the user for visible human approval before deleting archived team records or preserved Ensemble branches.", "The question must include the exact approval and denial option labels shown in the preview.", "Only if the user selects that exact approval option, call team_cleanup again with the same purge value, confirm_purge: true, and the confirm_token from the preview.");
  return lines.join(`
`);
}
function buildTeammateSystemPrompt(db, teamId, memberName, config) {
  const team = db.query("SELECT name FROM team WHERE id = ?").get(teamId);
  if (!team)
    return "";
  const lines = [
    `You are "${memberName}", a teammate in team "${team.name}". Use team_message to communicate. ${leadReportDirective(config)}`
  ];
  const pendingMessages = db.query("SELECT id, from_name, content FROM team_message WHERE team_id = ? AND to_name = ? AND delivered = 0 ORDER BY time_created ASC").all(teamId, memberName);
  if (pendingMessages.length > 0) {
    lines.push("", "--- Messages for you ---");
    const MAX_MSG = 500;
    for (const msg of pendingMessages) {
      const parsed = parseTaskResult(msg.content);
      if (parsed) {
        lines.push(formatTaskResult(msg.from_name, { ...parsed, details: truncate2(parsed.details, MAX_MSG) }));
      } else if (msg.content.length > MAX_MSG) {
        lines.push(`[From ${msg.from_name}]: ${msg.content.slice(0, MAX_MSG)}... (truncated)`);
      } else {
        lines.push(`[From ${msg.from_name}]: ${msg.content}`);
      }
      markDelivered(db, msg.id);
    }
    lines.push("--- End Messages ---");
  }
  return lines.join(`
`);
}
function buildTeamCompactionContext(db, teamId, role, memberName, config) {
  const team = db.query("SELECT name FROM team WHERE id = ?").get(teamId);
  if (!team)
    return "";
  const members = db.query("SELECT name, status FROM team_member WHERE team_id = ?").all(teamId);
  const taskCounts = db.query("SELECT status, COUNT(*) as count FROM team_task WHERE team_id = ? GROUP BY status").all(teamId);
  const countMap = {};
  for (const row of taskCounts) {
    countMap[row.status] = row.count;
  }
  const completed = countMap.completed ?? 0;
  const inProgress = countMap.in_progress ?? 0;
  const pending = countMap.pending ?? 0;
  const roleLine = role === "lead" ? `[Team Context] You are the lead of team "${team.name}".` : `[Team Context] You are a teammate named "${memberName}" in team "${team.name}".`;
  const memberList = members.map((m) => `${m.name} (${STATUS_DISPLAY[m.status] ?? m.status})`).join(", ");
  const membersLine = members.length > 0 ? `Members: ${memberList}` : "Members: none";
  const lines = [
    roleLine,
    membersLine,
    `Tasks: ${completed} completed, ${inProgress} in progress, ${pending} pending`
  ];
  if (role === "member" && memberName) {
    lines.push(`IMPORTANT: ${leadReportDirective(config)}`);
    const member = db.query("SELECT prompt FROM team_member WHERE team_id = ? AND name = ?").get(teamId, memberName);
    if (member?.prompt) {
      lines.push(`Your original task: ${truncate2(member.prompt, 300)}`);
    }
    const recentMsgs = db.query("SELECT from_name, content FROM team_message WHERE team_id = ? AND (from_name = ? OR to_name = ?) ORDER BY time_created DESC LIMIT 3").all(teamId, memberName, memberName);
    if (recentMsgs.length > 0) {
      lines.push("Recent context:");
      for (const msg of recentMsgs) {
        lines.push(`  [${msg.from_name}]: ${truncate2(msg.content, 200)}`);
      }
    }
  } else if (role === "member") {
    lines.push(`IMPORTANT: ${leadReportDirective(config)}`);
  }
  if (role === "lead") {
    const completedTasks = db.query("SELECT content, assignee FROM team_task WHERE team_id = ? AND status = 'completed' ORDER BY time_updated DESC LIMIT 5").all(teamId);
    if (completedTasks.length > 0) {
      lines.push("Recently completed:");
      for (const t of completedTasks) {
        lines.push(`  [completed] ${truncate2(t.content, 120)}${t.assignee ? ` (by ${t.assignee})` : ""}`);
      }
    }
  }
  return lines.join(`
`);
}

