        if (!row)
          return { text: `No team "${team}".` };
        const members = db.query("SELECT name, status FROM team_member WHERE team_id IN (SELECT id FROM team WHERE name = ?)").all(team);
        const summary = members.map((m) => `${m.name}: ${m.status}`).join(", ");
